use js_runtime::{ObjectId,Descriptor,PropertyKind};
fn raw_own(rt:&Runtime,value:Value,name:&str)->Option<Descriptor>{let id=rt.object_id(value).ok()?;rt.objects.get(id.0)?.iter_properties().find(|(key,_)|rt.string_units(key.0).iter().copied().eq(name.encode_utf16())).map(|(_,d)|d)}
fn raw_chain(rt:&Runtime,value:Value,name:&str)->Option<(ObjectId,Descriptor)>{let mut id=rt.object_id(value).ok()?;for _ in 0..32{let object=rt.objects.get(id.0)?;if let Some(d)=raw_own(rt,Value::Object(id),name){return Some((id,d))}id=object.prototype?;}None}
fn raw_data(rt:&Runtime,value:Value,name:&str)->Option<Value>{match raw_chain(rt,value,name)?.1.kind{PropertyKind::Data{value,..}=>Some(value),_=>None}}
fn raw_path(rt:&Runtime,mut value:Value,names:&[&str])->Option<Value>{for name in names{value=raw_data(rt,value,name)?;}Some(value)}
fn raw_property(rt:&Runtime,label:&str,value:Value,name:&str){eprintln!("MODE_DIAG:PROP:{label}:{}:{:?}:chain={:?}",name,raw_own(rt,value,name),raw_chain(rt,value,name));}
fn raw_object(rt:&Runtime,label:&str,value:Value){if let Ok(id)=rt.object_id(value){if let Some(o)=rt.objects.get(id.0){eprintln!("MODE_DIAG:OBJECT:{label}:{id:?}:kind={:?}:prototype={:?}:mapped={}",o.kind,o.prototype,o.arguments_map.len());}}else{eprintln!("MODE_DIAG:VALUE:{label}:{value:?}");}}
fn raw_source(rt:&mut Runtime,label:&str,value:Value)->JsResult<()>{let proto=Value::Object(rt.function_prototype);if let Some(method)=raw_data(rt,proto,"toString"){let source=rt.call(method,value,&[])?;if let Value::String(id)=source{let hex=rt.string_units(id).iter().map(|u|format!("{u:04x}")).collect::<String>();eprintln!("MODE_DIAG:SOURCE:{label}:{hex}");}}Ok(())}
fn mode_dump_raw(rt:&mut Runtime,label:&str,sources:bool)->JsResult<()>{
 eprintln!("MODE_DIAG:BOUNDARY:{label}");eprintln!("MODE_DIAG:FLAGS:{}:{}:{}:{}",rt.native_battle_mode_limit_enabled,rt.battle_mode_limit_attempts,rt.battle_mode_limit_domain_hits,rt.battle_mode_limit_getter_calls);
 for(name,id)in[("Object.prototype",rt.object_prototype),("Array.prototype",rt.array_prototype),("Function.prototype",rt.function_prototype),("String.prototype",rt.string_prototype)]{let v=Value::Object(id);raw_object(rt,name,v);for(key,d)in rt.objects[id.0].iter_properties(){let units=rt.string_units(key.0);let numeric=!units.is_empty()&&units.iter().all(|u|(48..=57).contains(u));if d.enumerable||numeric{eprintln!("MODE_DIAG:PROTO_KEY:{name}:{}:enumerable={}:numeric={}:descriptor={d:?}",String::from_utf16_lossy(units),d.enumerable,numeric);}}}
 let global=Value::Object(rt.global_object);for name in["Object","Array","parseInt","isNaN","isFinite","ed","__nativeTables","__nativeTableBoundary"]{raw_property(rt,"global",global,name);}
 for(name,value,key)in[("Object.prototype",Value::Object(rt.object_prototype),"hasOwnProperty"),("Function.prototype",Value::Object(rt.function_prototype),"call"),("String.prototype",Value::Object(rt.string_prototype),"split"),("Array.prototype",Value::Object(rt.array_prototype),"push")]{raw_property(rt,name,value,key);if let Some(f)=raw_data(rt,value,key){raw_object(rt,&format!("{name}.{key}"),f);raw_property(rt,&format!("{name}.{key}"),f,"call");}}
 for name in["Object","Array"]{if let Some(value)=raw_data(rt,global,name){for key in["prototype","isArray"]{raw_property(rt,name,value,key);}}}
 let Some(ed)=raw_data(rt,global,"ed")else{return Ok(())};raw_object(rt,"ed",ed);for name in["battleEngine","_battleEngineInstance","getDataTable","parseUseSkillCacheStageBattle","battle_camp"]{raw_property(rt,"ed",ed,name);}
 if sources{if let Some(Descriptor{kind:PropertyKind::Accessor{get:Some(f),..},..})=raw_own(rt,ed,"battleEngine"){raw_source(rt,"battleEngineGetter",f)?;}for name in["getDataTable","parseUseSkillCacheStageBattle","battle_camp"]{if let Some(f)=raw_data(rt,ed,name){if matches!(f,Value::Function(_)){raw_source(rt,name,f)?;}}else if let Some(Descriptor{kind:PropertyKind::Accessor{get:Some(f),..},..})=raw_own(rt,ed,name){raw_source(rt,&format!("{name}.getter"),f)?;}}}
 if let Some(camps)=raw_data(rt,ed,"battle_camp"){raw_object(rt,"battle_camp",camps);raw_property(rt,"battle_camp",camps,"enemy");}
 if let Some(engine)=raw_data(rt,ed,"_battleEngineInstance"){raw_object(rt,"engine",engine);for name in["config","battle_id","getBattleId"]{raw_property(rt,"engine",engine,name);}if let Some(config)=raw_data(rt,engine,"config"){raw_object(rt,"config",config);raw_property(rt,"config",config,"mode");if let Some(Value::String(id))=raw_data(rt,config,"mode"){eprintln!("MODE_DIAG:MODE:{}",String::from_utf16_lossy(rt.string_units(id)));}}
 if sources{if let Some(f)=raw_data(rt,engine,"getBattleId"){raw_source(rt,"getBattleId",f)?;}}
 for list in["unit_list","dead_unit_list","pet_list","dead_pet_list"]{if let Some(array)=raw_data(rt,engine,list){raw_object(rt,list,array);let Ok(id)=rt.object_id(array)else{continue};let values=rt.objects[id.0].iter_properties().filter_map(|(_,d)|match d.kind{PropertyKind::Data{value:Value::Object(id),..}=>Some(Value::Object(id)),_=>None}).take(2).collect::<Vec<_>>();for unit in values{raw_object(rt,"unit",unit);raw_property(rt,"unit",unit,"camp");raw_property(rt,"unit",unit,"info");if let Some(info)=raw_data(rt,unit,"info"){raw_object(rt,"unit.info",info);raw_property(rt,"unit.info",info,"ID");}}}}
 }
 for path in[&["__nativeTables","Param","Stage","UseSkillCacheStageBattle","StrValue"][..],&["__nativeTables","Param","Stage","UseSkillCacheHeroList","StrValue"][..]]{if let Some(value)=raw_path(rt,global,path){eprintln!("MODE_DIAG:TABLE_PATH:{path:?}:{value:?}");if let Value::String(id)=value{eprintln!("MODE_DIAG:TABLE_TEXT:{}:{}",path[3],String::from_utf16_lossy(rt.string_units(id)));}}}
 Ok(())
}
